10: const heroes=[{name:'Aelia',title:'The Fury',role:'ASSASSIN',icon:'⚔',tone:'#ef795f',glow:'#733c30',hp:100,atk:13,range:40,speed:122,cd:9,skill:'Ghoststep',desc:'Vanish and stun on reactivation; triple attack speed on stunned foes, with half defense.',logic:'FLANK'},{name:'Teneia',title:'The Bastion',role:'TANK',icon:'⬟',tone:'#91b5d8',glow:'#40566b',hp:175,atk:8,range:48,speed:78,cd:13,skill:'Stone Circle',desc:'Root nearby enemies and herself; triple defense while rooted.',logic:'GUARD'},{name:'Oola',title:'The Wildscent',role:'JUNGLER',icon:'◈',tone:'#d6aa6a',glow:'#665033',hp:120,atk:11,range:43,speed:108,cd:10,skill:'Maul',desc:'Lunge and maul. Reduced hero damage; double damage from tall grass.',logic:'SCOUT'},{name:'Brann',title:'The Longshot',role:'MARKSMAN',icon:'⌁',tone:'#d1c66d',glow:'#5a572e',hp:95,atk:10,range:190,speed:92,cd:8,skill:'Deadeye',desc:'Charged long-range shot that pierces armor.',logic:'BACKLINE'},{name:'Mira',title:'The Mender',role:'SUPPORT',icon:'✦',tone:'#a7d29a',glow:'#3c5a40',hp:110,atk:7,range:165,speed:94,cd:12,skill:'Verdant Pulse',desc:'Restore the most wounded ally and briefly shield the squad.',logic:'SUSTAIN'}];
11: const $=s=>document.querySelector(s), teamEl=$('#team-list'), canvas=$('#game'),ctx=canvas.getContext('2d');let active=0,started=false,paused=false,last=0,elapsed=0,toastTimer=0,moveTarget=null,focusTarget=null,feed=[];const keys={};let touchMove={x:0,y:0};
