13: function buildTeam(){teamEl.innerHTML='';heroes.forEach((h,i)=>{let card=document.createElement('div');card.className='team-card'+(i===active?' active':'');card.setAttribute('role','group');card.setAttribute('aria-label',`${h.name} squad card`);card.innerHTML=`<button class="team-select" type="button" aria-label="Control ${h.name}"><div class="card-top"><div class="portrait" style="--tone:${h.tone};--glow:${h.glow}">${h.icon}</div><div><div class="hero-name">${h.name} ${i===active?'· P1':''}</div><div class="hero-role">${h.role}</div></div></div><div class="hp-mini"><i id="hp-${i}" style="background:${h.tone}"></i></div></button><div class="card-bottom"><span>${i+1} · ${h.logic}</span><button class="mode" type="button" aria-label="Change ${h.name} battle logic">LOGIC ↻</button></div>`;card.querySelector('.team-select').onclick=()=>switchHero(i);card.querySelector('.mode').onclick=()=>{const modes=['FLANK','GUARD','SCOUT','BACKLINE','SUSTAIN','PUSH','FOLLOW','HOLD'];h.logic=modes[(modes.indexOf(h.logic)+1)%modes.length];buildTeam();say(`${h.name} logic: ${h.logic}`)};teamEl.appendChild(card)});renderHud()}
14: function renderHud(){let h=heroes[active];$('#hero-hud').innerHTML=`<div class="hud-box"><div class="hud-icon" style="color:${h.tone}">${h.icon}</div><div class="hud-info"><strong>${h.name} · ${h.title}</strong><span>${h.role} · ${h.hp} VIT</span></div></div><div class="hud-box"><div class="hud-icon">⌖</div><div class="hud-info"><strong>Basic attack</strong><span>${h.atk} power · ${h.range>100?'LONG':'MELEE'} range</span></div><div class="cooldown">SPACE<small>focus nearest</small></div></div><div class="hud-box"><div class="hud-icon">✧</div><div class="hud-info"><strong>${h.skill}</strong><span>${h.desc.split('.')[0]}.</span></div><div class="cooldown" id="skill-cd">Q<small>READY</small></div></div>`}
15: function switchHero(i){active=i;buildTeam();if(started)say(`Now controlling ${heroes[i].name}`)}function say(s){$('#toast').textContent=s;$('#toast').classList.add('show');toastTimer=2.2}function log(s,color='lime'){feed.unshift({time:Math.floor(elapsed),text:s,color});feed=feed.slice(0,5);$('#combat-log').innerHTML=feed.map(x=>`<div class="log-line"><em>${String(Math.floor(x.time/60)).padStart(2,'0')}:${String(x.time%60).padStart(2,'0')}</em><span class="${x.color}">${x.text}</span></div>`).join('')}
16: function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}function laneAt(y){return world.lanes.reduce((best,lane,i)=>Math.abs(y-world.lanes[best])<Math.abs(y-lane)?best:i,0)}function nearest(u,list){let n=null,d=1e9;for(const x of list){let z=dist(u,x);if(z<d){d=z;n=x}}return n}function inGrass(u){return world.jungles.some(j=>Math.hypot(u.x-j.x,u.y-j.y)<j.r)}
17: function initWorld(){moveTarget=null;focusTarget=null;world.heroes=heroes.map((h,i)=>({id:i,name:h.name,x:250+(i%2)*28,y:world.lanes[i%3]+(Math.floor(i/3)*22),lane:i%3,hp:h.hp,max:h.hp,atk:h.atk,range:h.range,speed:h.speed,cd:h.cd,timer:Math.random(),skill:0,stun:0,root:0,dead:0,dir:1,attackFlash:0,shield:0}));world.enemies=[['Rook',155,11,55,78,'tank','#ca8271'],['Vex',92,12,180,92,'marksman','#df9b82'],['Sable',105,12,48,112,'assassin','#dc8c7c'],['Morrow',100,9,150,90,'support','#d6a881'],['Grin',115,10,45,104,'fighter','#c37c70']].map((e,i)=>({name:e[0],x:1085+(i%2)*24,y:world.lanes[i%3]+(Math.floor(i/3)*24),lane:i%3,hp:e[1],max:e[1],atk:e[2],range:e[3],speed:e[4],kind:e[5],color:e[6],id:i,timer:Math.random(),stun:0,root:0,dead:0}));world.bullets=[];world.effects=[];world.minions=[];world.jungles=[{x:340,y:280,r:82},{x:520,y:280,r:76},{x:790,y:280,r:88},{x:1060,y:280,r:80},{x:340,y:520,r:82},{x:520,y:520,r:76},{x:790,y:520,r:88},{x:1060,y:520,r:80}];world.towers=world.lanes.flatMap((y,lane)=>[{side:'ally',x:175,y,hp:220,max:220,timer:0,lane},{side:'enemy',x:1225,y,hp:220,max:220,timer:0,lane}]);world.cores={ally:100,enemy:100};world.wave=0;world.waveTimer=3;world.gameOver=false;elapsed=0;feed=[];$('#combat-log').innerHTML='';log('Squad deployed to Veyra.')}
18: function useSkill(){if(!started||paused||world.gameOver)return;const u=world.heroes[active],h=heroes[active];if(u.dead>0){say(`${h.name} is down; wait to respawn.`);return}if(u.skill>0&&!(active===0&&u.stealth>0)){say(`${h.skill} recharging · ${Math.ceil(u.skill)}s`);return}const enemies=world.enemies.filter(e=>e.hp>0&&dist(u,e)<245);if(active===0){if(!u.stealth){u.stealth=4;u.skill=h.cd;u.speedBoost=0;say('Ghoststep · invisible. Press Q to strike!');world.effects.push({type:'ring',x:u.x,y:u.y,t:.8,color:h.tone})}else{u.stealth=0;let t=nearest(u,enemies);if(t){t.stun=1.35;u.speedBoost=3;u.defenseDown=3;deal(u,t,0,25);say('Ghoststep · ambush! Target stunned');log('Aelia opened with a stunning strike.')}else say('Revealed · no enemy in striking range');}}
19: else{u.skill=h.cd;if(active===1){u.root=3.4;u.guard=3.4;let caught=0;for(const e of enemies){e.root=3.4;e.hp-=24;caught++}world.effects.push({type:'ring',x:u.x,y:u.y,t:1,color:h.tone});say(`Stone Circle · ${caught} foes rooted; defense tripled`);log(`Teneia rooted ${caught} enemies.`)}else if(active===2){let t=nearest(u,world.enemies.filter(e=>e.hp>0));if(t&&dist(u,t)<265){let d=dist(u,t),step=Math.min(62,d);u.x+=(t.x-u.x)/Math.max(d,1)*step;u.y+=(t.y-u.y)/Math.max(d,1)*step;let damage=t.kind==='marksman'||t.kind==='support'?25:38;if(inGrass(u))damage*=2;t.hp-=damage;t.stun=.35;world.effects.push({type:'hit',x:t.x,y:t.y,t:.5,color:h.tone});say(`Maul · ${damage} damage${inGrass(u)?' · grass ambush':''}`)}else say('No target close enough to maul')}else if(active===3){let t=nearest(u,world.enemies.filter(e=>e.hp>0));if(t&&dist(u,t)<360){t.hp-=45;t.stun=.45;world.effects.push({type:'shot',x:u.x,y:u.y,x2:t.x,y2:t.y,t:.45,color:h.tone});say('Deadeye · armor-piercing shot')}else say('No enemy in Deadeye range')}else{let t=nearest(u,world.heroes.filter(a=>a.hp<a.max&&a.dead<=0));if(t){let healed=Math.min(55,t.max-t.hp);t.hp+=healed;t.shield=4;world.effects.push({type:'ring',x:t.x,y:t.y,t:.9,color:h.tone});say(`Verdant Pulse · ${t.name} +${Math.round(healed)} health`);log(`Mira restored ${t.name}.`)}else say('Your squad is at full health')}}}
