21: function attack(i){if(!started||paused||world.gameOver)return;const u=world.heroes[i];if(u.dead>0)return;let targets=livingTargets(),t=focusTarget&&focusTarget.hp>0?focusTarget:nearest(u,targets);if(!t){say('No enemy in reach');return}if(dist(u,t)>u.range+25){if(i===active){moveTarget={x:t.x,y:t.y};say('Moving into attack range')}return}deal(u,t,i)}
22: function deal(u,t,i,damage){let power=damage??u.atk;if(i===0&&u.speedBoost>0&&t.stun>0)power*=3;if(i===2&&inGrass(u))power*=2;if(t.kind==='core'){world.cores.enemy=Math.max(0,world.cores.enemy-power);log('Enemy core takes damage!')}else{t.hp=Math.max(0,t.hp-power);if(world.enemies.includes(t)&&t.hp<=0){t.dead=7;log(`${heroes[i].name} defeated ${t.name}.`)}if(t.side==='enemy'&&t.max&&t.hp<=0)log('Enemy tower destroyed!')}u.attackFlash=.2;world.effects.push({type:'hit',x:t.x,y:t.y,t:.28,color:heroes[i].tone});if(i===0&&t.stun>0){u.speedBoost=2.2;u.defenseDown=2.2}}
23: function move(u,x,y,dt){let dx=x-u.x,dy=y-u.y,d=Math.hypot(dx,dy);if(d>3){let step=Math.min(d,u.speed*dt);u.x+=dx/d*step;u.y+=dy/d*step;u.lane=laneAt(u.y);u.dir=dx>=0?1:-1}}
