25: function update(dt){if(!started||paused||world.gameOver)return;elapsed+=dt;world.waveTimer-=dt;if(world.waveTimer<=0){world.wave++;world.waveTimer=24;for(let lane=0;lane<3;lane++)for(let i=0;i<2;i++){world.minions.push({x:215,y:world.lanes[lane]+(i-.5)*17,hp:48,max:48,atk:6,range:28,speed:57,side:'blue',lane,timer:.3});world.minions.push({x:1185,y:world.lanes[lane]+(i-.5)*17,hp:48,max:48,atk:6,range:28,speed:57,side:'red',lane,timer:.3})}log(`Wave ${world.wave} marches into the ward.`)}
